using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using DepartmentFinancialRecords.API.Data;using DepartmentFinancialRecords.API.Models;
namespace DepartmentFinancialRecords.API.Controllers;
[ApiController][Route("api/students")] public sealed class StudentsController:ControllerBase{private readonly ApplicationDbContext _db;public StudentsController(ApplicationDbContext db)=>_db=db;[HttpGet]public async Task<ActionResult<IEnumerable<Student>>> Get()=>Ok(await _db.Students.AsNoTracking().OrderBy(x=>x.FullName).ToListAsync());[HttpGet("{id:int}")]public async Task<ActionResult<Student>> Get(int id){var x=await _db.Students.FindAsync(id);return x is null?NotFound():Ok(x);}[HttpPost]public async Task<ActionResult<Student>> Post(Student student){if(string.IsNullOrWhiteSpace(student.StudentId)||string.IsNullOrWhiteSpace(student.FullName))return BadRequest("Student ID and full name are required.");if(await _db.Students.AnyAsync(x=>x.StudentId==student.StudentId))return Conflict("Student ID already exists.");student.Id=0;_db.Students.Add(student);await _db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=student.Id},student);}[HttpPut("{id:int}")]public async Task<IActionResult> Put(int id,Student value){var x=await _db.Students.FindAsync(id);if(x is null)return NotFound();x.StudentId=value.StudentId;x.FullName=value.FullName;x.Course=value.Course;x.YearLevel=value.YearLevel;x.Rfid=value.Rfid;x.Status=value.Status;await _db.SaveChangesAsync();return Ok(x);}[HttpDelete("{id:int}")]public async Task<IActionResult> Delete(int id){var x=await _db.Students.FindAsync(id);if(x is null)return NotFound();_db.Students.Remove(x);await _db.SaveChangesAsync();return NoContent();}}
